update content_bodies set title = '【ふるさとCM大賞NARA2025】天川村「心の深呼吸」', description = '【作品概要】
修験道の聖地でもある天川村で、深く、ゆっくりと「心の深呼吸」をするような
静寂の登山体験へ誘う動画を制作しました。
一歩一歩、山を登るごとに心が洗われていくような感覚、そして山頂から広がる絶景に
心が解き放たれる瞬間が表現できるよう心がけました。
日常の喧騒を離れ、自分自身と向き合い、心の奥底からリフレッシュできる特別な時間を
天川村で見つけてみませんか？

■ふるさとCM大賞NARAについてはコチラ↓
https://www.naratv.co.jp/furusato-cm/

＃天川村' where id = 'sTheQYHEFUnS45SAFvGW2';
update content_bodies set title = '[Furusato CM Grand Prize NARA 2025] Amano Village ''Deep Breathing of the Heart''', description = '[Overview]
In Amano Village, a sacred place for Shugendo, we created a video that invites viewers to experience a serene mountain climb, as if taking a deep, slow ''breath of the heart.''
With each step up the mountain, we aimed to express the sensation of having one''s heart cleansed, and the moment when the heart is set free by the breathtaking view from the summit.
Why not find a special time in Amano Village to step away from the hustle and bustle of daily life, face yourself, and refresh from the depths of your heart?

■ For more information about the Furusato CM Grand Prize NARA, click here:
https://www.naratv.co.jp/furusato-cm/

#AmanoVillage' where id = 'wKikY2aL3z5RymrTAnloj';
update content_bodies set title = 'Enchanting Tokyo  - Is this really Tokyo? -  Volcano Island OSHIMA  (Full ver.) / 絶景！大島 三原山火口をドローン空撮', description = 'OSHIMA Island
1 hour 45 minutes (minimum) from central Tokyo by high-speed jet ferry . 
Enjoy the island’s dynamic scenery, with views such as Mt. Mihara, the volcanic crater you can see close, a vast ‘desert’ and ‘Fudeshima’, the brush-like rock protruding from the sea surface. Be it camping or cycling, there are activities for you to immerse yourself in the rich nature of the island. 
Full of charm, Oshima Island is waiting to enchant   you. 

Oshima tourist information:
https://www.gotokyo.org/jp/destinations/izu-and-ogasawara-islands/oshima-island/index.html

────────────────────────────
東京都心から高速ジェット船で最短1時間45分。
間近で見ることのできる三原山の火口、広大な「砂漠」、海面から突き出た岩「筆島」などのダイナミックな景観と、自転車、キャンプなど豊かな自然の中で楽しむアクティビティ。
魅力あふれる大島でお待ちしています。

大島観光情報
https://www.gotokyo.org/jp/destinations/izu-and-ogasawara-islands/oshima-island/index.html



#ドローン #空撮 #火山 #火口 #裏砂漠 #四輪バギー #大島 #伊豆大島 #絶景 #自転車 #登山 #椿 #キャンプ
#drone #volcano #crater #japan #tokyo #izu #island #enchanting #enchantingtokyo' where id = 'hxbcAhY1eWsmdnLEELcRS';
