update content_bodies set title = 'Enchanting Tokyo HACHIJOJIMA Island (Full ver.)／八丈島', description = 'Hachijojima Island, which is less than an hour’s flight from Tokyo, is an island where you can enjoy the great outdoors. With one of the highest precipitation rates in Japan, Hachijojima has its own unique environment including giant ferns and potholes carved into the rock by ever-flowing spring water. On the island, you can enjoy hiking as well as running and fishing. After enjoying physical activities, visitors can relax in a natural hot spring surrounded by rich nature, making it the perfect environment for a refreshing weekend getaway. 

Access
・Airplane (Haneda Airport-Hachijojima Airport) 3 flights/day [approximately 55 minutes, one way]
・Boat (Takeshiba Pier, Tokyo- Hachijojima, Sokodo or Yaene Port): Runs daily [10 hours and 20 minutes, one way]

Hachijojima Tourist Information
https://www.gotokyo.org/en/destinations/izu-and-ogasawara-islands/hachijojima-island/index.html 

東京から飛行機で1時間弱で到着する八丈島は、大自然と向き合える島です。日本でも降水量がトップクラスとなる八丈島は、巨大なシダ植物や、枯れることのない湧水によって岩盤が削られたポットホールなど独自の自然を育んでいます。島ではトレッキングはもちろんランニングや釣りなども楽しめます。身体を動かすアクティビティを楽しんだ後は、豊かな自然に囲まれた天然温泉でリラックスすることができ、週末のリフレッシュには最適な環境です。

アクセス
・飛行機（羽田空港－八丈島空港）：1日3便［片道約55分］
・船（東京・竹芝桟橋－八丈島・底土または八重根港）：毎日運航［片道約10時間20分］

八丈島観光情報
https://www.gotokyo.org/jp/destinations/izu-and-ogasawara-islands/hachijojima-island/index.html

#drone #japan #tokyo #hachijojima #izu #island #enchanting #travel #trip #ドローン #空撮 #八丈島 #絶景' where id = 'turSSo4GvZ-gNqdK6BzXA';
update content_bodies set title = 'Enchanting Tokyo HACHIJOJIMA Island (Full ver.)／八丈島', description = 'Hachijojima Island, which is less than an hour’s flight from Tokyo, is an island where you can enjoy the great outdoors.
With one of the highest precipitation rates in Japan, Hachijojima has its own unique environment including giant ferns and potholes carved into the rock by ever-flowing spring water.
On the island, you can enjoy hiking as well as running and fishing.
After enjoying physical activities, visitors can relax in a natural hot spring surrounded by rich nature, making it the perfect environment for a refreshing weekend getaway.

