update content_bodies set title = 'Enchanting Tokyo AOGASHIMA Island (Full ver.)／青ヶ島', description = 'Aogashima Island, located 358 kilometers (222 miles) south of urban Tokyo in the Pacific Ocean, was the only Japanese location selected as the “World’s Top 13 Most Beautiful Views to See Before you Die” by a US-based NGO, thereby attracting attention from around the world. The video “Enchanting Tokyo AOGASHIMA Island” introduces the unique landscape of the island, including the world-famous double caldera and geothermic “hingya” steam eruptions. The video also explores the island’s way of life and beliefs that coexist in harmony with nature. 

Access
・Helicopter (Hachijojima Airport-Aogashima Heliport): 1 flight/day [20 minutes, one way]
・Boat (Hachijojima, Sokodo or Yaene Port-Aogashima, Sanpo Port): 4-5 trips weekly [2 hours and 30 minutes, one way]

Aogashima Tourist Information
https://www.gotokyo.org/en/destinations/izu-and-ogasawara-islands/aogashima-island/index.html 

東京から南に358㎞離れた太平洋上に浮かぶ青ヶ島は、アメリカ・環境保護NGOによって「死ぬまでに見るべき世界の絶景13選」に日本で唯一選出（2014年）され、世界中から注目を集めています。Enchanting Tokyo AOGASHIMA Island（動画）では、世界的にもめずらしい二重カルデラや、地熱によって水蒸気が噴出する「ひんぎゃ」など、他には見られない景観を紹介しています。さらに、自然と共生する島のくらしや、信仰などにも迫っています。

アクセス
・ヘリコプター（八丈島空港－青ヶ島ヘリポート）：1日1便［片道約20分］
・船（八丈島・底土または八重根港－青ヶ島・三宝港）：週4・5回［片道約2時間30分］

青ヶ島観光情報
https://www.gotokyo.org/jp/destinations/izu-and-ogasawara-islands/aogashima-island/index.html

#drone #volcano #japan #tokyo #aogashima #izu #island #enchanting #travel #trip #ドローン #空撮 #火山 #青ヶ島 #絶景' where id = 'GFzZhkuvJRmhPQeATQM7d';
