update content_bodies set title = 'Enchanting Tokyo　7-Minute Miracle/7分間の奇跡', description = 'Dateline Tokyo journalist Charli James went behind the scenes with the Shinkansen bullet train cleaning crew to film their "7-Minute Miracle" turnaround.

都の仕事で来日したアメリカ人のビデオ記者チャーリーさんが、東京で「すごい！面白い！」と感じたことを取材しました。
この動画は、新幹線がわずかな時間で清掃を終えて再び出発していく様子に関心を持ち、東京駅で撮影。迅速で正確な清掃により
快適な旅が実現されている様子を「７分間の奇跡」と題して制作されたものです。

Dateline Tokyo : http://www.metro.tokyo.jp/ENGLISH/ABOUT/DATELINE/dateline_index.htm

 #enchanting' where id = 'tJrHvvTeItovqPCrK4AD5';
update content_bodies set title = 'Enchanting Tokyo 7-Minute Miracle/7分間の奇跡', description = 'Dateline Tokyo journalist Charli James went behind the scenes with the Shinkansen bullet train cleaning crew to film their "7-Minute Miracle" turnaround.

An American video journalist, Charli, who came to Japan for work, reported on what he found "amazing and interesting" in Tokyo.
This video was filmed at Tokyo Station, focusing on the Shinkansen''s ability to complete cleaning in a very short time and depart again. It showcases how comfortable travel is made possible through rapid and precise cleaning, titled "7-Minute Miracle."

Dateline Tokyo: http://www.metro.tokyo.jp/ENGLISH/ABOUT/DATELINE/dateline_index.htm

 #enchanting' where id = 'b_kX1WvMrdEbCFzqw317z';
