update content_bodies set title = '[Kagura Boys] Nakagoe Iwato Kagura''s First Regular Performance of the Year', description = 'On April 4, 2021, the first regular performance of the Nakagoe Iwato Kagura, a traditional performing art passed down in this region, was held at the Nakagoe Kagura Hall in Aso City, Naminokawa.' where id = 'mKi8143nCLziRtUmZ7qvA';
update content_bodies set title = '千年の草原', description = '九州熊本県阿蘇地方。
27万年前からの度重なる大噴火で出来たカルデラと呼ばれるくぼ地に、約5万人が暮らす、世界でも珍しい場所です。
カルデラの中央には、今も噴煙を上げる活火山阿蘇山がそびえ、その周辺には日本最大の草原地帯が広がります。
この唯一無二の空間は、国立公園、ユネスコ世界ジオパーク、世界農業遺産にも認定されています。

#阿蘇の草原 #サステナブル #千年の草原' where id = 'cPBQkCk5ZQL-RDdFMRjpR';
update content_bodies set title = 'Thousand-Year Grassland', description = 'Kumamoto Prefecture, Aso region in Kyushu.

This is a rare place in the world where about 50,000 people live in a caldera, a depression formed by repeated massive eruptions over the past 270,000 years.

At the center of the caldera stands the active volcano Mount Aso, which still emits smoke, and surrounding it is Japan''s largest grassland area.

This unique space has been designated as a national park, a UNESCO Global Geopark, and a World Agricultural Heritage site.

#AsoGrassland #Sustainable #ThousandYearGrassland' where id = '-KMIMHkE2jQ-nPdh3nzjs';
update content_bodies set title = '今だけ！愛媛をお得に旅行できる「ぐるっとえひめ旅」', description = '愛媛県への旅行者を対象に、バスや船、タクシーを利用して、愛媛ならではの周遊プランが楽しめる「ぐるっとえひめ旅」のプロモーション動画です。
愛媛の魅力をたっぷり詰め込んだ様々なコースをご用意していますので、ぜひ、この機会に愛媛を満喫してください。

