update content_bodies set title = '【優良賞】004 盛岡城 Let''s try『Tojo』', description = '800年の歴史を持つ南部家。その居城となった盛岡城。日本100名城に選ばれ東北三名城の一つにも数えられながらも、天守が無い為かネームバリューが弱い。でも、そんな盛岡城にも魅力があります！復元天守がなくても江戸時代への思いを馳せることができる場所がここにある！！との想いから『登城』をモチーフとした盛岡城のプロモーション的動画を目指しました。
また、会社のPCやスマホでの視聴を想定して字幕にて説明（日本語と英語）を入れております。' where id = 'G8IHlNkRo4yhPoG_Cv97l';
update content_bodies set title = '[Excellent Award] 004 Morioka Castle Let''s try ''Tojo''', description = 'The Nanbu clan has an 800-year history. Morioka Castle, which served as their residence, is selected as one of Japan''s 100 Famous Castles and is counted among the three famous castles of Tohoku. However, perhaps due to the absence of a main keep, its name recognition is weak. Still, Morioka Castle has its own charm! Even without a restored main keep, there is a place here where you can reflect on the Edo period!! With this sentiment in mind, we aimed to create a promotional video for Morioka Castle themed around ''Castle Climbing.'' 
Additionally, we have included explanations in subtitles (in Japanese and English) for viewing on company PCs and smartphones.' where id = '8Cp1n3Hocda-NDzGy1jNy';
