update content_bodies set title = 'LOOK UP  Kumamoto City , JAPAN  4K 熊本市  Full ver【広報課】', description = '「見上げる」「良くなる」「元気を出す」という意味の「LOOK UP」。
旅人の女性が熊本市に降り立ち、風土に触れるうちに、
いつの間にか街に魅了され軽快に前を向いて歩き出すというストーリー。
終盤では、「パワー・元気」の象徴であるカラフルな風船が、
熊本城の上空に向け飛んでいきます。
「落ちこんだり、元気がなくなったりした時は見上げてほしい。この街には私たちを支えてくれる熊本城がある。皆で上を向いて行こう！」そんなメッセージが込められています。

Music By 竜馬四重奏

