update content_bodies set title = 'LOOK UP Kumamoto City, JAPAN 4K 熊本市 Full ver【広報課】', description = '"LOOK UP" means "to look up," "to improve," and "to cheer up." 
A female traveler arrives in Kumamoto City and, as she experiences the local culture, 
she becomes captivated by the city and starts walking forward with a light heart. 
In the latter part, colorful balloons, symbolizing "power and energy," 
fly up into the sky above Kumamoto Castle. 
"When you feel down or lack energy, I want you to look up. This city has Kumamoto Castle, which supports us. 
Let''s all look up together!" This message is conveyed. 

Music By 竜馬四重奏 

