update content_bodies set title = '大洲川まつり 花火大会 -冬の陣-(2025.1.11 18:00-18:45)', description = '輝かしい新年の幕開けとして開催される大洲川まつり花火大会-冬の陣-へ行ってきました。
チャンネル登録者さんから情報を頂いて予定を調整しての参戦です。
冬の花火は研ぎ澄まされたエッジの効いた鋭い感じだったように思いました。
しかし、寒かった。

