[Sagamiko Pleasure Forest] offers various leisure / activities such as hot springs, camping, and drones, as well as the main amusement park. 

Experience the amazing winter illuminations 
from 2021/11/13 (Sat) -2022/4/3 (Sun)
Opens from 4pm-9pm

Admission + Lift 
Adults (including seniors) 1,500 yen
Children 1,100 yen 

Night Free Pass 
Adults (including seniors) 2,800 yen 
Children 2,200 yen

* The entrance fee includes the lift ride fee.


Admission rules

Rainy weather OK
* Sales may be postponed depending on the weather. 
* Free pass tickets used at amusement parks during the day can also be used at night attractions.

