update content_bodies set title = '東広島の自然～安芸津～', description = 'ひろしま杜氏のふるさと、安芸津。
ゆるやかな海岸線から瀬戸内海の島しょ美を眺めることができます。
５月中旬～６月上旬になると赤崎海岸では、じゃがいもの白い花があたり一面に咲き広がります。' where id = 'SsOBzC9cdKuzgSSKKZslH';
update content_bodies set title = 'Nature of Higashihiroshima - Aki-tsu', description = 'The hometown of Hiroshima''s sake brewers, Aki-tsu.
You can enjoy the beauty of the islands in the Seto Inland Sea from the gentle coastline.
From mid-May to early June, the white flowers of potatoes bloom all over Akasaki Beach.' where id = '7MB9H14Wta-Xv6W-Bs9SE';
