update content_bodies set title = 'SHOCHU TOURISM ～Discover Miyazaki Culture With Shochu～県西＆県南エリア（Western＆Southern Area）', description = '宮崎県は本格焼酎出荷量9年連続日本一を誇る焼酎の産地です。県では、焼酎づくり体験に加え、夜神楽等の鑑賞や通常は飲食で利用しない文化財を会場にしたメーカーズプレミアムディナーなど、本県の歴史・文化を感じながら、焼酎の魅力に触れるインバウンド向けの酒蔵ツーリズムを推進しています。宮崎の大自然や伝統とともに歩んでいる個性豊かな蔵元の見学と、宮崎グルメと焼酎のペアリングをぜひ体験してみてください。

Miyazaki Prefecture is a shochu-producing region that boasts the largest shipment of authentic shochu in Japan for 9 consecutive years. In promotion of Shochu Tourism, the prefecture not only offers opportunities for shochu-making, but tourists can also explore the charms of shochu and experience Miyazaki’s history and culture through activities such as watching Yokagura performances, enjoying Premium Dinner with shochu-craftsmen at cultural and heritage venues that are usually not used for dining. Come join us in touring our unique distillery that encompasses Miyazaki’s great nature and tradition, as well as try shochu pairing with Miyazaki’s local delicacies.' where id = 'NMHN1_3_Ii1Ul7oAaDVIR';
update content_bodies set title = 'SHOCHU TOURISM ～Discover Miyazaki Culture With Shochu～ Western & Southern Area', description = 'Miyazaki Prefecture is a shochu-producing region that boasts the largest shipment of authentic shochu in Japan for 9 consecutive years.
In promotion of Shochu Tourism, the prefecture not only offers opportunities for shochu-making, but tourists can also explore the charms of shochu and experience Miyazaki’s history and culture through activities such as watching Yokagura performances, enjoying Premium Dinner with shochu-craftsmen at cultural and heritage venues that are usually not used for dining.
Come join us in touring our unique distillery that encompasses Miyazaki’s great nature and tradition, as well as try shochu pairing with Miyazaki’s local delicacies.' where id = 'eTfP_SVitRusG461g9CIn';
