update content_bodies set title = '【美術館への誘い】4-3. 富山県美術館 / Toyama Prefectural Museum of Art and Design', description = '日本には、数多くの個性的で魅力溢れる美術館があります。本ビデオシリーズでは、４つのテーマから全国各地の美術館（計24館）をご紹介します。それぞれの豊かなコレクションや優れた建築を通して、日本のアートの世界をお楽しみください。

「美術館への誘い」
Ⅰ：自然とともにある美術館
Ⅱ：建築家が自作を語る美術館
Ⅲ：アーティストのための美術館／アーティストによる美術館
Ⅳ：デザインを新しい視点から発信する美術館

Ⅳ：デザインを新しい視点から発信する美術館
最先端のプロダクツから、グラフィック、各地の伝統工芸、民藝、家具、道具などのジャンルを対象にユニークな活動を行っている６つの美術館を紹介します。

「デザインを新しい視点から発信する美術館」プレイリスト（多言語字幕にてご覧いただけます。）
https://youtube.com/playlist?list=PLR82S6MFHeIkkddAGCtCU16VaCeTTBq7b

