update content_bodies set title = '[Invitation to Museums] 4-3. Toyama Prefectural Museum of Art and Design', description = 'Japan is home to many unique and captivating museums. In this video series, we introduce museums from all over the country (a total of 24) based on four themes. Enjoy the world of Japanese art through their rich collections and outstanding architecture.

"Invitation to Museums"
I: Museums in Harmony with Nature
II: Museums Where Architects Speak of Their Works
III: Museums for Artists / Museums by Artists
IV: Museums Presenting Design from a New Perspective

IV: Museums Presenting Design from a New Perspective
We will introduce six museums that engage in unique activities across genres such as cutting-edge products, graphics, traditional crafts from various regions, folk art, furniture, and tools.

"Museums Presenting Design from a New Perspective" Playlist (Available with multilingual subtitles.)
https://youtube.com/playlist?list=PLR82S6MFHeIkkddAGCtCU16VaCeTTBq7b

